-- VERIFICATION 2 : status mixes (tutor requirement - no column all-same)
SELECT 'Customer' AS Table_Name, Status, COUNT(*) AS Records FROM Customer GROUP BY Status ORDER BY Status;
SELECT 'Item' AS Table_Name, Status, COUNT(*) AS Records FROM Item GROUP BY Status ORDER BY Status;
SELECT 'Promotion' AS Table_Name, Status, COUNT(*) AS Records FROM Promotion GROUP BY Status ORDER BY Status;
SELECT 'Payment' AS Table_Name, Status, COUNT(*) AS Records FROM Payment GROUP BY Status ORDER BY Status;
