SELECT 'Returns' AS Table_Name, Status, COUNT(*) AS Records FROM Returns GROUP BY Status ORDER BY Status;
SELECT 'Voucher' AS Table_Name, Status, COUNT(*) AS Records FROM Voucher GROUP BY Status ORDER BY Status;

-- VERIFICATION 3 : trigger calculations are consistent (all must return 0)
SELECT COUNT(*) AS bad_order_totals FROM Orders o WHERE o.TotalAmount <> (SELECT NVL(SUM(d.Subtotal),0) FROM OrderDetails d WHERE d.OrderNo = o.OrderNo);
SELECT COUNT(*) AS bad_refund_totals FROM Returns r WHERE r.TotalRefundAmount <> (SELECT NVL(SUM(rd.RefundAmount),0) FROM ReturnDetails rd WHERE rd.ReturnID = r.ReturnID);
SELECT COUNT(*) AS bad_balances FROM Member m WHERE m.PointsBalance <> (SELECT NVL(SUM(CASE WHEN pt.TransType = 'Earn' THEN pt.Point ELSE -pt.Point END),0) FROM PointTransaction pt WHERE pt.MemberID = m.MemberID);

-- VERIFICATION 4 : sample of auto-generated IDs and computed values
SELECT OrderNo, OrderDateTime, TotalAmount, CustomerID FROM Orders WHERE ROWNUM <= 5;
